  'hub.p.biz': 'നിങ്ങൾ ഡോക്യുമെന്റ് ഉണ്ടാക്കുന്ന ബിസിനസുകൾ. അവയുടെ പേര്, വിലാസം, GSTIN, ബാങ്ക് വിവരം, ലോഗോ, ഒപ്പ് എന്നിവ നിങ്ങളുടെ ഡോക്യുമെന്റിൽ പ്രിന്റ് ആകും.',
  'hub.p.party': 'നിങ്ങൾ ബിൽ കൊടുക്കുന്ന അല്ലെങ്കിൽ വാങ്ങുന്ന ആളുകളും സ്ഥാപനങ്ങളും. ഏത് ടൂളിലും പേര് ടൈപ്പ് ചെയ്ത് തിരഞ്ഞെടുത്താൽ വിലാസം, സംസ്ഥാനം, GSTIN നിറയും.',
  'hub.p.item': 'സാധനങ്ങളും സർവീസുകളും, അവയുടെ HSN/SAC കോഡ്, യൂണിറ്റ്, റേറ്റ്, GST സഹിതം. ഏത് ടൂളിലും തിരഞ്ഞെടുത്താൽ വരി നിറയും.',
  'hub.p.doc': 'ഈ ബ്രൗസറിൽ സേവ് ചെയ്ത എല്ലാ ഡോക്യുമെന്റും. തുറക്കൽ, കോപ്പി, പെയ്ഡ് എന്ന് മാർക്ക് ചെയ്യൽ എന്നിവ അത് ഉണ്ടാക്കിയ ടൂളിൽ നിന്ന് ചെയ്യുക.',
