  "s.gstadv": "ഈ അഡ്വാൻസിൽ GST ഉൾപ്പെടുന്നു (സർവീസ്)",
  "s.h.gstadv": "സർവീസിന് കിട്ടിയ അഡ്വാൻസിന് ടിക്ക് ചെയ്യുക: അപ്പോൾ രസീത്, അതിലെ GST കാണിക്കുന്ന രസീത് വൗച്ചർ ആകും. സാധനങ്ങൾക്കുള്ള അഡ്വാൻസിന് GST ഇല്ല; സാധാരണ അഡ്വാൻസ് രസീത് തന്നെ രസീത് വൗച്ചറായി പ്രവർത്തിക്കും.",
