  "s.w.wages": "ബേസിക് സാലറി ഗ്രോസിന്റെ പകുതിയിൽ കുറവാണ്. ലേബർ കോഡുകൾ പ്രകാരം അധിക അലവൻസുകൾ PF-നും ഗ്രാറ്റുവിറ്റിക്കും വേതനമായി കണക്കാക്കും.",
