  "bk.badfile": "ഈ ഫയൽ വായിക്കാനായില്ല. .xlsx അല്ലെങ്കിൽ .csv ഫയൽ തിരഞ്ഞെടുക്കുക.",
  "bk.nohead": "കോളം തലക്കെട്ടുകൾ കണ്ടെത്താനായില്ല (കുറഞ്ഞത് ഡോക്യുമെന്റ് നമ്പറും ഐറ്റവും വേണം). ഞങ്ങളുടെ ടെംപ്ലേറ്റിൽ നിന്ന് തുടങ്ങുക.",
