  "g3.p.avail": "ലഭ്യമായ ക്രെഡിറ്റ്",
  "g3.p.cf": "അടുത്ത കാലയളവിലേക്ക് ബാക്കിയുള്ള ക്രെഡിറ്റ്",
  "g3.note": "CGST ആക്ടിലെ സെക്ഷൻ 49 ഉം ചട്ടം 88A യും പ്രകാരമുള്ള സെറ്റ്-ഓഫ്: ആദ്യം IGST ക്രെഡിറ്റ് ഉപയോഗിക്കുന്നു, പിന്നീട് CGST, SGST/UTGST ക്രെഡിറ്റ്; CGST, SGST ക്രെഡിറ്റുകൾ പരസ്പരം ഉപയോഗിക്കില്ല; റിവേഴ്സ് ചാർജ് ടാക്സ് ക്യാഷായി തന്നെ അടയ്ക്കണം. നിങ്ങൾ ഫയൽ ചെയ്യുമ്പോൾ പോർട്ടൽ അന്തിമ സെറ്റ്-ഓഫ് ചെയ്യും.",
  "g3.w.zr": "ബിൽ {no} കയറ്റുമതി അല്ലെങ്കിൽ SEZ ബില്ലാണ്, പക്ഷേ CGST/SGST കാണിക്കുന്നു. Zero rated വിതരണങ്ങളിൽ IGST മാത്രമേ ഉണ്ടാകൂ.",
  "g3.w.rcmv": "വൗച്ചർ {no}: റിവേഴ്സ് ചാർജ് ടാക്സ് CGST + SGST ആയി എടുത്തിരിക്കുന്നു. സപ്ലയർ മറ്റൊരു സംസ്ഥാനത്തെ ആണെങ്കിൽ (IGST) ബോക്സുകൾ മാറ്റുക.",
  "g3.w.nogstin": "{p} ൽ നിന്നുള്ള പർച്ചേസ് ബിൽ {no} ന് ശരിയായ സപ്ലയർ GSTIN ഇല്ല, അതിനാൽ അതിന്റെ ITC GSTR-2B യിൽ കാണില്ല.",
  "g3.w.2b": "ബോക്സ് 4(A)(5) ലെ ITC നിങ്ങൾ സേവ് ചെയ്ത പർച്ചേസ് ബില്ലുകളിൽ നിന്നും ചെലവുകളിൽ നിന്നുമാണ്. നിങ്ങളുടെ GSTR-2B യിൽ കാണുന്നത് മാത്രം ക്ലെയിം ചെയ്യുക; GSTR-2B കണക്ക് കുറവാണെങ്കിൽ അത് ടൈപ്പ് ചെയ്യുക.",
  "g3.w.neg": "ലഭ്യമായ ക്രെഡിറ്റ് പൂജ്യത്തിൽ താഴെയാണ്: റിവേഴ്സലുകൾ ക്രെഡിറ്റിനേക്കാൾ കൂടുതലാണ്. വ്യത്യാസം ക്യാഷായി അടയ്ക്കണം; നിങ്ങളുടെ അക്കൗണ്ടന്റിനോട് ചോദിക്കുക.",
  /* gstr2b */
  "nav.gstr2b": "GSTR-2B മാച്ചർ",
