  "g2.file": "നിങ്ങളുടെ GSTR-2B ഫയൽ തുറക്കുക (JSON അല്ലെങ്കിൽ Excel)",
  "g2.drop": "അല്ലെങ്കിൽ ഫയൽ ഇവിടെ ഇടുക",
  "g2.privacy": "ഫയൽ ഈ ബ്രൗസറിൽ മാത്രമാണ് വായിക്കുന്നത്. ഒരിടത്തും അപ്‌ലോഡ് ചെയ്യില്ല.",
  "g2.from": "പർച്ചേസ് ബില്ലുകൾ മുതൽ",
