  "g2.regh": "ഈ തീയതികളിലെ നിങ്ങളുടെ പർച്ചേസ് ബില്ലുകളിൽ നിന്ന്, പോർട്ടലിലെ Matching Offline Tool ലേഔട്ടിൽ ഉണ്ടാക്കിയ Excel.",
  "g2.loaded": "ഈ ബ്രൗസറിലെ ഡേറ്റാ ഹോമിൽ {n} പർച്ചേസ് ബില്ലുകൾ കണ്ടെത്തി.",
  "g2.reading": "{f} വായിക്കുന്നു…",
  "g2.read": "GSTR-2B വായിച്ചു: {n} ഡോക്യുമെന്റുകൾ, GSTIN {g}, കാലയളവ് {p}.",
  "g2.empty": "ഈ ഫയലിൽ ബില്ലുകൾ കണ്ടെത്തിയില്ല. GST പോർട്ടലിൽ നിന്ന് ഡൗൺലോഡ് ചെയ്ത GSTR-2B JSON അല്ലെങ്കിൽ Excel തുറക്കുക.",
  "g2.bad": "ഈ ഫയൽ വായിക്കാനായില്ല. GST പോർട്ടലിൽ നിന്ന് GSTR-2B വീണ്ടും ഡൗൺലോഡ് ചെയ്യുക (JSON അല്ലെങ്കിൽ Excel) എന്നിട്ട് ആ ഫയൽ തുറക്കുക.",
  "g2.for": "GSTIN {g} ന്റെ GSTR-2B മാച്ച്, കാലയളവ് {p}",
  "g2.k.2b": "GSTR-2B യിലെ ITC",
  "g2.k.books": "നിങ്ങളുടെ പർച്ചേസ് ബില്ലുകളിലെ ITC",
  "g2.k.ok": "മാച്ച് ആയ ITC",
  "g2.k.n": "മാച്ച് ആയ ഡോക്യുമെന്റുകൾ",
  "g2.w.gstin": "ഈ GSTR-2B GSTIN {a} ന്റേതാണ്, പക്ഷേ തിരഞ്ഞെടുത്ത ബിസിനസിന്റെ GSTIN {b} ആണ്. ശരിയായ ബിസിനസ് തിരഞ്ഞെടുക്കുക.",
  "g2.s.ok": "മാച്ച് ആയി",
  "g2.s.diff": "തുകയോ തീയതിയോ വ്യത്യസ്തം",
  "g2.s.numdiff": "ബിൽ നമ്പർ വ്യത്യസ്തം",
  "g2.s.only2b": "GSTR-2B യിൽ ഉണ്ട്, നിങ്ങളുടെ പർച്ചേസ് ബില്ലുകളിൽ ഇല്ല",
  "g2.s.onlybooks": "നിങ്ങളുടെ പർച്ചേസ് ബില്ലുകളിൽ ഉണ്ട്, GSTR-2B യിൽ ഇല്ല",
  "g2.s.noitc": "GSTR-2B പറയുന്നു: ITC ലഭ്യമല്ല",
  "g2.s.nofile": "ഈ GSTR-2B യിൽ ഒന്നുമില്ലാത്ത സപ്ലയർമാർ",
  "g2.h.ok": "അതേ സപ്ലയർ, നമ്പർ, തുക, തീയതി. ഈ ക്രെഡിറ്റ് ക്ലെയിം ചെയ്യാം.",
  "g2.h.diff": "രണ്ടിലും ഉണ്ട്, പക്ഷേ കണക്കുകൾ വ്യത്യസ്തമാണ്. സപ്ലയറോട് ബിൽ ഒത്തുനോക്കുക; GSTR-2B യിൽ കാണുന്നത് മാത്രം ക്ലെയിം ചെയ്യുക.",
  "g2.h.numdiff": "അതേ സപ്ലയറും തുകയും, പക്ഷേ ബിൽ നമ്പർ വേറെ രീതിയിൽ എഴുതിയിരിക്കുന്നു. സാധാരണ ടൈപ്പിംഗ് വ്യത്യാസമാണ്: നിങ്ങളുടെ എൻട്രി തിരുത്തുക.",
  "g2.h.only2b": "സപ്ലയർ ഈ ബില്ലുകൾ റിപ്പോർട്ട് ചെയ്തിട്ടുണ്ട്, പക്ഷേ അവ നിങ്ങളുടെ പുസ്തകത്തിൽ സേവ് ചെയ്തിട്ടില്ല. സാധനമോ സേവനമോ കിട്ടിയെങ്കിൽ എൻട്രി ചെയ്യുക, ഇല്ലെങ്കിൽ സപ്ലയറോട് തിരുത്താൻ പറയുക.",
  "g2.h.onlybooks": "ഈ തീയതികളിലെ നിങ്ങളുടെ ബില്ലുകൾ സപ്ലയർ ഇതുവരെ റിപ്പോർട്ട് ചെയ്തിട്ടില്ല. GSTR-2B യിൽ വരുന്നതുവരെ ITC ക്ലെയിം ചെയ്യരുത്; സപ്ലയറെ ഓർമ്മിപ്പിക്കുക.",
  "g2.h.noitc": "പോർട്ടൽ ITC ലഭ്യമല്ല എന്ന് കാണിക്കുന്ന ബില്ലുകൾ (ഉദാഹരണത്തിന് വിതരണ സ്ഥലം സപ്ലയറുടെ സംസ്ഥാനത്താണ്, അല്ലെങ്കിൽ സമയപരിധി).",
  "g2.h.nofile": "ഈ കാലയളവിൽ ഈ സപ്ലയർമാർ നിങ്ങളുടെ ഒരു ബില്ലും റിപ്പോർട്ട് ചെയ്തിട്ടില്ല. അവർ GSTR-1 ഫയൽ ചെയ്തിട്ടുണ്ടാവില്ല.",
