  "td.no.m": "TDS ഇല്ല: മാസത്തെ പേയ്മെന്റ് {l} ന് മുകളിലല്ല.",
  "td.no.y": "ഇതുവരെ TDS ഇല്ല: വർഷത്തെ ആകെ {l} നുള്ളിൽ തന്നെയാണ്. അതിന് മുകളിലെത്തിക്കുന്ന പേയ്മെന്റിൽ TDS പിടിക്കുക.",
  "td.no.q": "ഇതുവരെ TDS ഇല്ല: ഈ വർഷം ഈ വിൽപനക്കാരനിൽ നിന്നുള്ള വാങ്ങൽ {l} ന് മുകളിലല്ല.",
  "td.catch": "ഈ പേയ്മെന്റ് വർഷത്തെ ആകെ തുകയെ പരിധിക്ക് മുകളിലെത്തിക്കുന്നു, അതിനാൽ TDS മുഴുവൻ ആകെ തുകയിലും കണക്കാക്കിയിരിക്കുന്നു, TDS ഇല്ലാതെ മുമ്പ് നൽകിയ {y} ഉൾപ്പെടെ. അതിൽ കുറച്ചിന് ഇതിനകം TDS പിടിച്ചിട്ടുണ്ടെങ്കിൽ, വ്യത്യാസം മാത്രം പിടിക്കുക.",
  "td.nopan": "ശരിയായ PAN ഇല്ലെങ്കിൽ നിരക്ക് 20% അല്ലെങ്കിൽ സാധാരണ നിരക്കിന്റെ ഇരട്ടി (സാധനം വാങ്ങലിന് 5%), ഇവയിൽ കൂടുതലുള്ളത്. പണം വാങ്ങുന്നയാളോട് PAN ചോദിക്കുക.",
  "td.trans": "10 ഓ അതിൽ കുറവോ ഗുഡ്സ് വാഹനങ്ങളുള്ള ട്രാൻസ്പോർട്ടർ PAN സഹിതം പ്രഖ്യാപനം നൽകിയാൽ TDS ഇല്ലാതെ പണം നൽകാം.",
  "td.q": "കഴിഞ്ഞ വർഷം നിങ്ങളുടെ ടേൺഓവർ ₹10 കോടിക്ക് മുകളിലായിരുന്നെങ്കിൽ മാത്രം, ഈ വിൽപനക്കാരനിൽ നിന്നുള്ള വർഷത്തെ വാങ്ങലിൽ ₹50 ലക്ഷത്തിന് മുകളിലുള്ള ഭാഗത്തിന് മാത്രം TDS പിടിക്കുക.",
  "td.ib": "ടാക്സ് ഓഡിറ്റ് ഇല്ലാത്ത വ്യക്തി നൽകുന്ന വാടകയ്ക്ക് TDS ഒരു തവണ മാത്രമേ പിടിക്കൂ, വർഷത്തിലെയോ വാടക കാലാവധിയിലെയോ അവസാന മാസത്തെ വാടകയിൽ നിന്ന്.",
  "td.oldnote": "2026 ഏപ്രിൽ 1 ന് മുമ്പുള്ള പേയ്മെന്റുകൾക്ക് ആദായനികുതി ആക്ട്, 1961 ബാധകമാണ്: പഴയ സെക്ഷൻ നമ്പർ ഉപയോഗിക്കുക.",
  "td.h.reg": "നിങ്ങൾ പിടിച്ച TDS (നിങ്ങളുടെ പേയ്മെന്റ് വൗച്ചറുകളിൽ നിന്ന്)",
  "td.h.regh": "voucher.niveshsahayak.in ലോ ആപ്പിലോ TDS നിരക്കോടെ സേവ് ചെയ്ത വൗച്ചറുകൾ, മാസവും സെക്ഷനും അനുസരിച്ച്, അടയ്ക്കേണ്ട തീയതി സഹിതം.",
