  "pl.stockh": "വിൽപന, വാങ്ങൽ, ചെലവുകൾ, പണം, കുടിശ്ശിക എന്നിവ നിങ്ങളുടെ സേവ് ചെയ്ത രേഖകളിൽ നിന്ന് വരുന്നു; സ്റ്റോക്ക് മൂല്യം സ്റ്റോക്ക് രജിസ്റ്ററിൽ നിന്ന്. രജിസ്റ്റർ മൂല്യം ഉപയോഗിക്കാൻ സ്റ്റോക്ക് ബോക്സുകൾ ഒഴിച്ചിടുക, അല്ലെങ്കിൽ സ്റ്റോക്ക് എണ്ണിയ മൂല്യം ടൈപ്പ് ചെയ്യുക. ഫിക്സഡ് അസറ്റ്, തേയ്മാനം (ഡിപ്രീസിയേഷൻ), ക്യാപിറ്റൽ, ലോൺ, ഡ്രോയിംഗ്സ് എന്നിവ ടൈപ്പ് ചെയ്ത വരികളായി ചേർക്കുക.",
