  "pl.tbas": "{d} ലെ ട്രയൽ ബാലൻസ്",
  "pl.tbh": "ഓരോ അക്കൗണ്ടും അതിന്റെ ഹെഡോടെ. ലാഭനഷ്ട അക്കൗണ്ടുകൾ കാലയളവിനുള്ളിലെ ഇടപാടുകൾ; ബാലൻസ് ഷീറ്റ് അക്കൗണ്ടുകൾ അവസാന ദിവസത്തെ ബാലൻസ്. ഒരു വരി മറ്റൊരു ഹെഡിൽ പെടുന്നതാണെങ്കിൽ അതിന്റെ ഹെഡ് മാറ്റുക.",
